-- Production-parity fingerprint of every relation the fixture holds: columns (type, not null, default, identity), constraints, foreign keys
-- inside the fixture, indexes, triggers, row level security, grants (the PostgreSQL 17 MAINTAIN privilege 'm' is ignored so that PostgreSQL 16
-- and 17 compare alike) and view text. Run the same query on live (read-only) and here; run.sh compares with parity-live-2026-11-09.txt.
with t(r) as (select unnest(array['catalogue.providers','catalogue.courses','catalogue.campuses','catalogue.course_campuses','ref.countries','ref.subdivisions','pipeline.campus_regional_class','search.course_documents','pipeline.layer4_block_decisions','scholarship.scholarships','scholarship.criteria','scholarship.nationality_readings','scholarship.course_mappings','pipeline.layer4_review_items','pipeline.scholarship_ai_reviews','pipeline.platform_toolset_settings','catalogue.provider_assets','pipeline.evidence_artifacts','pipeline.sources','pim.entity_registry','ref.fields_of_study','ref.study_levels','ref.provider_types','pipeline.layer3_interpretations','pipeline.platform_toolsets','ref.currencies','ref.regions','scholarship.scopes','scholarship.criterion_groups','scholarship.offering_cycles','scholarship.award_tiers','scholarship.course_financial_calculations','catalogue.provider_collection_memberships','ref.institution_collections','ranking.observation_provider_links','ranking.observations','ranking.editions','ranking.systems','ranking.publisher_institutions','catalogue.course_fees','security.layer4_search_blocked_scholarships','security.layer4_active_blocks','security.layer4_search_blocked_courses','security.layer4_search_blocked_providers','security.provider_hidden_v1']))
select r,
 left(md5(coalesce((select string_agg(a.attname||' '||format_type(a.atttypid,a.atttypmod)||case when a.attnotnull then ' NN' else '' end||coalesce(' D '||pg_get_expr(d.adbin,d.adrelid),'')||case when a.attidentity<>'' then ' I'||a.attidentity::text else '' end, ', ' order by a.attnum) from pg_attribute a left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum where a.attrelid=c.oid and a.attnum>0 and not a.attisdropped),'')),8) cols,
 left(md5(coalesce((select string_agg(k.conname||' '||pg_get_constraintdef(k.oid), ', ' order by k.conname) from pg_constraint k where k.conrelid=c.oid and k.contype<>'f'),'')),8) cons,
 left(md5(coalesce((select string_agg(k.conname||' '||pg_get_constraintdef(k.oid), ', ' order by k.conname) from pg_constraint k where k.conrelid=c.oid and k.contype='f' and (select n2.nspname||'.'||c2.relname from pg_class c2 join pg_namespace n2 on n2.oid=c2.relnamespace where c2.oid=k.confrelid) in (select r from t)),'')),8) fks,
 left(md5(coalesce((select string_agg(pg_get_indexdef(i.indexrelid), ', ' order by pg_get_indexdef(i.indexrelid)) from pg_index i where i.indrelid=c.oid),'')),8) idx,
 coalesce((select string_agg(tg.tgname, ',' order by tg.tgname) from pg_trigger tg where tg.tgrelid=c.oid and not tg.tgisinternal),'') trg,
 c.relrowsecurity::int::text||c.relforcerowsecurity::int::text rls,
 coalesce((select string_agg(replace(x, 'm/', '/'), ',' order by x) from unnest(c.relacl::text[]) x where x !~ '^(postgres|supabase_\w+)='),'') acl,
 (select count(*) from pg_policy p where p.polrelid=c.oid) pol,
 case when c.relkind='v' then left(md5(pg_get_viewdef(c.oid)),8) end vdef
from t left join pg_class c on c.oid=to_regclass(t.r) order by 1;
